from itertools import permutations, combinations
from sympy import MatrixSymbol, Matrix, Array, symbols
from sympy.tensor.array.expressions.array_expressions import ArrayTensorProduct, ArrayContraction, ArrayDiagonal, PermuteDims
from sympy.tensor.array.expressions.from_array_to_matrix import convert_array_to_matrix
M, N = (MatrixSymbol(s, 2, 2) for s in ('M', 'N'))
subs = {M: Matrix([[1, 2], [3, 4]]), N: Matrix([[5, 6], [7, 8]])}
def explicit(e):
    e = e.xreplace(subs)
    if hasattr(e, 'as_explicit'):
        e = e.as_explicit()
    if hasattr(e, 'shape'):
        return Array(e)
    return e
count = 0
for base in (ArrayTensorProduct(2*M, 3*N).doit(), ArrayContraction(ArrayTensorProduct(2*M, 3*N), (1, 2))):
    for perm in permutations(range(len(base.shape))):
        e = PermuteDims(base, list(perm))
        r = convert_array_to_matrix(e)
        assert explicit(e) == explicit(r), (e, r)
        count += 1
for axes in combinations(range(4), 2):
    for cls in (ArrayContraction, ArrayDiagonal):
        e = cls(ArrayTensorProduct(2*M, 3*N), axes)
        r = convert_array_to_matrix(e)
        assert explicit(e) == explicit(r), (e, r)
        count += 1
assert ArrayTensorProduct(1).doit() == 1
assert convert_array_to_matrix(ArrayTensorProduct(2*M).doit()) == 2*M
print('Passed', count, 'explicit coefficient, permutation, contraction and diagonal checks')
